import { headers } from 'next/headers'

export default async function Dashboard() {
  try {
    // Server-side fetch requires absolute URLs for routes on this app.
    const requestHeaders = await headers()
    const host = requestHeaders.get('host')
    if (!host) throw new Error('Missing request host')
    const origin = `${requestHeaders.get('x-forwarded-proto') ?? 'http'}://${host}`

    const [analytics, notifications, settings] = await Promise.all(
      ['/api/analytics', '/api/notifications', '/api/settings'].map(async (path) => {
        const response = await fetch(new URL(path, origin))
        if (!response.ok) throw new Error(`Failed to fetch ${path}: ${response.status}`)
        return response.json()
      }),
    )

    return (
      <div>
        <h2>Dashboard Content</h2>
        <h3>Analytics</h3>
        <pre>{JSON.stringify(analytics, null, 2)}</pre>
        <h3>Notifications</h3>
        <pre>{JSON.stringify(notifications, null, 2)}</pre>
        <h3>Settings</h3>
        <pre>{JSON.stringify(settings, null, 2)}</pre>
      </div>
    )
  } catch {
    return (
      <div>
        <h2>Dashboard Content</h2>
        <p>Dashboard data is unavailable.</p>
      </div>
    )
  }
}

